import bg from './bg'
import bgPlural from './bg-plural'
import en from './en'

const BY_LOCALE = { bg, 'en-US': en }

/**
 * The story text for a language and a form of address.
 * Bulgarian readers addressed in the plural get the "вие" edition
 * (generated by tools/make-plural.mjs); English "they" already fits.
 */
export function storyContent(locale, address) {
  const isBg = locale === 'bg' || locale?.startsWith('bg')
  if (isBg && address === 'p') return bgPlural
  return BY_LOCALE[locale] ?? (isBg ? bg : en)
}
